from html.parser import HTMLParser
import sys
class P(HTMLParser):
    def __init__(self): super().__init__(); self.href=None; self.text=[]; self.items=[]
    def handle_starttag(self, tag, attrs):
        if tag=='a': self.href=dict(attrs).get('href'); self.text=[]
    def handle_data(self, data):
        if self.href is not None: self.text.append(data)
    def handle_endtag(self, tag):
        if tag=='a' and self.href is not None:
            t=' '.join(''.join(self.text).split())
            if t and self.href.startswith('http'): self.items.append((t,self.href))
            self.href=None
p=P(); p.feed(open(sys.argv[1],encoding='utf-8',errors='ignore').read())
for t,u in p.items[:20]: print(t,'\\t',u)
PY
done"

